'use strict';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageIssue='',storageConflict=false,profileEdit=null,saveTimer,previousFocus;
const STORAGE_KEY='owa-prepayment-audit-v1';
let state={saved:0};
const phoneKey=p=>String(p||'').replace(/\D/g,'').replace(/^00/,'');
function save(){try{state.saved=Date.now();localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageIssue='';updateSaveNotice();return true}catch{storageIssue='Not saved: browser storage is unavailable. Keep this page open.';updateSaveNotice();return false}}
const icons={home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-8h6v8"/>',file:'<path d="M6 3h8l4 4v14H6Z"/><path d="M14 3v5h5M9 12h6M9 16h6"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-3a6 6 0 0 1 12 0v3M17 5a3 3 0 0 1 0 6m1 3a5 5 0 0 1 3 5"/>',chat:'<path d="M3 4h18v13H8l-5 4Z"/><path d="M7 9h10M7 12h7"/>',shield:'<path d="m12 3 8 3v6c0 4-8 9-8 9S4 16 4 12V6Z"/><path d="m8 12 3 3 5-6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',upload:'<path d="M4 15v5h16v-5M12 16V3m-5 5 5-5 5 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>'};
const ico=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.file}</svg>`;
function updateSaveNotice(){const t=$('#save-time');if(t){t.textContent=storageIssue||'Saved on this browser';t.classList.toggle?.('unsaved',!!storageIssue)}const b=$('#storage-notice');if(b){b.textContent=storageIssue;b.hidden=!storageIssue}}
function storageBanner(){return `<div class="storage-warning" id="storage-notice" role="alert" ${storageIssue?'':'hidden'}>${esc(storageIssue)}</div>${storageConflict?'<button class="btn small" onclick="window.location.reload()">Reload saved version</button>':''}`}
function toast(text){$('#toast').textContent=text+(storageIssue?' · '+storageIssue:'');$('#toast').classList.remove('hidden');clearTimeout(saveTimer);saveTimer=setTimeout(()=>$('#toast').classList.add('hidden'),5000)}
function saveLabel(){return `<span class="savehint ${storageIssue?'unsaved':''}" id="save-time">${esc(storageIssue||'Saved on this browser')}</span>`}
function modal(title,html){previousFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modalback" onclick="if(event.target===this)closeModal()"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modalhead"><h2>${title}</h2><button class="close" aria-label="Close dialog" onclick="closeModal()">×</button></div><div class="modalbody"><div class="errorbox" id="modal-errors" role="alert" tabindex="-1"></div>${html}</div></section></div>`;document.body.style.overflow='hidden';$('#app')?.setAttribute?.('inert','');setTimeout(()=>$('.modal button, .modal input')?.focus(),10)}
function closeModal(){profileEdit=null;$('#modal-root').innerHTML='';document.body.style.overflow='';$('#app')?.removeAttribute?.('inert');previousFocus?.focus()}
document.addEventListener('keydown',e=>{if(!$('.modal'))return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const els=[...document.querySelectorAll('.modal button:not([disabled]),.modal input:not([disabled]),.modal select,.modal textarea,.modal a')].filter(x=>x.offsetParent);if(!els.length)return;if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0].focus()}}});
// Unified journey: a single application record links intake, payment and the questionnaire.
const freshIntake=()=>({package:'',step:0,name:'',email:'',phone:'',applicants:[0,1].map(()=>({age:null,national:null,assets:null,married:null,children:null})),verifiedEmail:'',terms:false,payment:'unpaid',paidAt:null});
function journey(){return state.journey||(state.journey=freshIntake())}
let demoSession=false,preView='choose',otpChallenge=null,otpAttempts=0,otpNextSend=0,resumeEmail='',paymentOutcome='success';
const serviceFee=()=>journey().package==='couples'?1799:999;
const courtFee=()=>journey().package==='couples'?1900:950;
const money=n=>n.toLocaleString('en-US');
const packageTitle=()=>journey().package==='couples'?'Wills for Couples':'Individual Will';
const activeApplicants=()=>journey().applicants.slice(0,journey().package==='couples'?2:1);
function scopeErrors(){const j=journey(),e=[];if(!j.package)e.push('Choose an Individual Will or Wills for Couples.');activeApplicants().forEach((a,i)=>{const who=i?'Your partner':'You';for(const[k,label]of [['age','age 21 or above'],['national','non-UAE nationality'],['assets','assets in the UAE']]){if(a[k]===null)e.push(who+': answer the question about '+label+'.');else if(a[k]===false)e.push(who+': this answer needs a team check before payment.')}});return e}
function aboutErrors(){const e=[];if(!journey().name.trim())e.push('Enter your full name as shown on your passport.');activeApplicants().forEach((a,i)=>{if(a.married===null)e.push((i?'Your partner':'You')+': answer the marriage question.');if(a.children===null)e.push((i?'Your partner':'You')+': answer the children-under-18 question.')});return e}
function contactErrors(email=journey().email,withPhone=true){const e=[];if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim()))e.push('Enter a valid email address.');if(withPhone&&!/^\+[1-9]\d{6,14}$/.test('+'+phoneKey(journey().phone)))e.push('Enter your phone number with country code, for example +971 50 000 0001.');return e}
function preErrors(e){const el=$('#pre-errors');if(!el)return toast(e[0]);el.innerHTML='<strong>Please check:</strong><ul>'+e.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>';el.classList.add('show');el.focus();el.scrollIntoView({block:'center',behavior:'smooth'})}
function preGo(view){if(storageConflict)return toast('Reload the saved version first.');if(journey().payment==='pending'&&view!=='pending')return toast('Check the pending payment before changing the application.');preView=view;if(['choose','about','checkout','payment'].includes(view)){journey().step=['choose','about','checkout','payment'].indexOf(view)+1;save()}render();window.scrollTo({top:0,behavior:'instant'});$('#main')?.focus({preventScroll:true})}
function startIntake(pkg){if(journey().payment==='paid'){preGo(demoSession?'success':'resume');return}if(pkg)journey().package=pkg;preGo(journey().payment==='pending'?'pending':'choose')}
function pickPackage(v){if(journey().payment!=='unpaid'&&journey().payment!=='failed')return;journey().package=v;journey().terms=false;save();render();document.querySelector('[data-package-choice="'+v+'"]')?.focus({preventScroll:true})}
function preAnswer(i,k,v){journey().applicants[i][k]=v;save();render();document.querySelector(`input[name="${i}-${k}"][value="${v}"]`)?.focus({preventScroll:true})}
function preInput(k,v){const j=journey();j[k]=v;if(k==='email'){j.verifiedEmail='';otpChallenge=null;demoSession=false}save()}
function preNext(step){const e=step===1?scopeErrors():[...scopeErrors(),...aboutErrors()];if(e.length)return preErrors(e);preGo(step===1?'about':'checkout')}
function yesNo(i,k,label){const v=journey().applicants[i][k];return `<fieldset class="pre-question"><legend>${label} <span aria-hidden="true">*</span></legend><div class="pre-options">${[[true,'Yes'],[false,'No']].map(([val,t])=>`<label class="pre-radio ${v===val?'selected':''}"><input type="radio" name="${i}-${k}" value="${val}" ${v===val?'checked':''} onchange="preAnswer(${i},'${k}',${val})">${t}</label>`).join('')}</div></fieldset>`}
function preProgress(){const n=journey().step;return `<ol class="pre-progress" aria-label="Application progress">${['Choose your Will','About you','Review','Payment'].map((s,i)=>`<li ${n===i+1?'aria-current="step"':''} class="${n===i+1?'active':n>i+1?'done':''}"><span>${n>i+1?'✓':i+1}</span>${s}</li>`).join('')}</ol>`}
// Illustrative stock photos; not OWA customers or endorsements. Individual: https://images.unsplash.com/photo-1494790108377-be9c29b29330 ; Couples: https://unsplash.com/photos/QUYTz7c0dos (JD-Photos).
const OWA_PEOPLE_IMAGES={"individual": "data:image/jpeg;base64,", "couples": "data:image/jpeg;base64,"};
function prePackage(p,choose=true){const couple=p==='couples',selected=journey().package===p;
return `<button type="button" data-package-choice="${p}" class="card pre-package ${couple?'couples':'individual'} ${choose&&selected?'selected':''}" aria-pressed="${selected}" onclick="${choose?'pickPackage':'startIntake'}('${p}')"><span class="cardbody"><span class="pre-package-photo" aria-hidden="true"><img src="${OWA_PEOPLE_IMAGES[p]}" alt="" width="600" height="800" decoding="async"></span><span class="pre-package-copy"><span class="pre-package-title"><span><span class="pre-package-count">${couple?'FOR YOU AND YOUR PARTNER':'FOR YOU'}</span><span class="pre-package-name">${couple?'Wills for Couples':'Individual Will'}</span></span><span class="choice-indicator" aria-hidden="true">✓</span></span><span class="premium-package-detail">${couple?'Two separate Wills. One person can complete both, with different wishes for each.':'One Will for your assets, your beneficiaries and the people you appoint.'}</span></span><span class="pre-package-action">${selected?'Selected':'Choose this option'} ${ico('arrow')}</span></span></button>`}

function preChoose(){return `<div class="pre-intro pagehead"><div><div class="eyebrow">START YOUR APPLICATION · STEP 1 OF 4</div><h1>Who is your Will for?</h1><p class="sub">Start with who needs a Will. Then answer a few questions about you. Review the fee before you pay.</p></div><div class="pre-intro-art" aria-hidden="true"><span class="pre-intro-sheet"></span><span class="pre-intro-seal">owa</span></div></div><div class="pre-sectionline"><span>01</span><strong>Choose your Will</strong><small>You can change your choice before payment</small></div><div class="grid2 pre-package-grid">${['individual','couples'].map(p=>prePackage(p)).join('')}</div>${journey().package?`<div class="card pre-gap pre-scope"><div class="pre-scope-heading"><span>02</span><strong>Confirm a few essentials</strong></div><div class="cardbody"><div class="grid2">${activeApplicants().map((a,i)=>`<section><h3>${i?'Your partner':'You'}</h3>${yesNo(i,'age',i?'Is your partner aged 21 or above?':'Are you aged 21 or above?')}${yesNo(i,'national',i?'Is your partner a non-UAE national?':'Are you a non-UAE national?')}${yesNo(i,'assets',i?'Does your partner own assets in the UAE?':'Do you own any assets in the UAE?')}</section>`).join('')}</div><p class="pre-scope-note">These questions check our standard service scope. If an answer is No, the team will need to check your application before you pay.</p></div></div>`:''}<div class="actions"><button class="link small" onclick="preHelp()">Need help choosing?</button><button class="btn primary" onclick="preNext(1)">Continue ${ico('arrow')}</button></div>`}
function preAbout(){return `<div class="pagehead"><div class="eyebrow">STEP 2 OF 4 · ABOUT YOU</div><h1>A little about you and your family.</h1><p class="sub">These details help us prepare your questionnaire. No document uploads are needed yet.</p></div><div class="cols"><div class="card pre-details-card"><div class="cardbody"><label class="field">Your full name *<input autocomplete="name" aria-required="true" value="${esc(journey().name)}" oninput="preInput('name',this.value)"><span class="hint">Use your name as shown on your passport.</span></label><div class="grid2 pre-gap">${activeApplicants().map((a,i)=>`<section><h3>${i?'Your partner':'You'}</h3>${yesNo(i,'married',i?'Is your partner married?':'Are you married?')}${yesNo(i,'children',i?'Does your partner have any children under 18?':'Do you have any children under 18?')}</section>`).join('')}</div>${journey().package==='couples'?'<p class="small muted">You’ll enter your partner’s full identity and contact details after payment. Each Will can have different children and appointments.</p>':''}</div></div><aside class="callout pre-about-note"><div><strong>You won’t need to enter this twice</strong><p>Your answers carry into the questionnaire and help us show the relevant sections. You choose your beneficiaries and appointments later.</p><p>You can edit these details later.</p></div></aside></div><div class="actions"><button class="btn" onclick="preGo('choose')">← Back</button><button class="btn primary" onclick="preNext(2)">Review your package ${ico('arrow')}</button></div>`}
function emailControls(){const j=journey();if(j.verifiedEmail&&j.verifiedEmail===j.email.trim().toLowerCase())return `<div class="callout green">${ico('check')}<span>Email verified. You’re ready for the payment step.</span></div>`;return `${otpChallenge&&otpChallenge.purpose==='checkout'?otpForm():`<button class="btn soft" type="button" onclick="sendDemoOtp('checkout')">Send my verification code</button>`}`}
function otpForm(){return `<div class="subtlebox"><p class="small">Enter the six-digit code for <strong>${esc(otpChallenge.email)}</strong>.</p><p class="small muted">Testing only: use <strong>123456</strong>. No email is sent. Code expires in 10 minutes.</p><label class="field">Verification code<input id="demo-otp" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="6-digit code" onkeydown="if(event.key==='Enter'){event.preventDefault();verifyDemoOtp()}"></label><div class="row wrap pre-gap"><button class="btn primary small" type="button" onclick="verifyDemoOtp()">Verify code</button><button class="link small" type="button" onclick="sendDemoOtp('${otpChallenge.purpose}')">Resend code</button></div></div>`}
function sendDemoOtp(purpose){if(Date.now()<otpNextSend)return toast('Please wait '+Math.ceil((otpNextSend-Date.now())/1000)+' seconds before requesting another code.');const email=(purpose==='resume'?resumeEmail:journey().email).trim().toLowerCase();const e=contactErrors(email,purpose!=='resume');if(e.length)return preErrors(e);otpChallenge={email,purpose,expires:Date.now()+600000};otpAttempts=0;otpNextSend=Date.now()+30000;render();$('#demo-otp')?.focus()}
function verifyDemoOtp(){if(!otpChallenge)return;const c=otpChallenge;if(Date.now()>c.expires||otpAttempts>=5){preErrors(['This code expired or reached its attempt limit. Request a new code.']);return}if($('#demo-otp').value.trim()!=='123456'){otpAttempts++;preErrors(['Incorrect test code. Use 123456.']);return}if(c.purpose==='resume'){if(c.email!==journey().email.trim().toLowerCase())return preErrors(['No matching saved test application on this browser. Check the email or start an application.']);demoSession=true;otpChallenge=null;if(journey().payment==='paid'){preView='success'}else if(journey().payment==='pending')preView='pending';else{journey().verifiedEmail=c.email;preView=journey().step===3?'checkout':journey().step===2?'about':'choose'}render();return}if(c.email!==journey().email.trim().toLowerCase())return preErrors(['Your email changed. Request a new code.']);journey().verifiedEmail=c.email;demoSession=true;otpChallenge=null;save();render()}
function startPayment(){const j=journey();if(j.payment==='paid'){preGo(demoSession?'success':'resume');return}if(j.payment==='pending'){preGo('pending');return}let e=[...scopeErrors(),...aboutErrors(),...contactErrors()];if(!j.terms)e.push('Read and accept the test Service Terms.');if(e.length)return preErrors(e);j.payment='pending';j.attemptReference='OWA-TEST-'+Date.now().toString(36).toUpperCase();save();preView='pending';render();const attempt=j.attemptReference;setTimeout(()=>{if(journey().attemptReference!==attempt||journey().payment!=='pending')return;if(paymentOutcome==='success')completePayment();else if(paymentOutcome==='declined'){journey().payment='failed';save();preView='payment';render();preErrors(['Your test payment was declined. Please retry; your answers are saved.'])}},800)}
function prePending(){return `<section class="pre-centered"><span class="pill amber">Payment status pending</span><h1>We’re checking your payment.</h1><p class="sub">Your answers are saved. Please don’t pay again yet.</p><div class="card pre-gap"><div class="cardbody"><p>${packageTitle()} · OWA fee <strong>AED ${money(serviceFee())}</strong></p><p class="small muted">Reference: ${esc(journey().attemptReference||'OWA-TEST')}</p><p class="pre-court">Court fee AED ${money(courtFee())} is paid separately to ADJD.</p></div></div><p class="small muted">Testing: a successful result continues automatically. If you selected “Pending” in Test controls, use “Resolve pending test payment” there to continue.</p><button class="btn" onclick="openTesting()">Open test controls</button></section>`}
function preResume(){return `<section class="pre-centered"><div class="eyebrow">PICK UP WHERE YOU LEFT OFF</div><h1>Resume your application.</h1><p class="sub">Use the email entered at checkout. This file can resume one saved test application on this browser.</p><div class="card pre-gap"><div class="cardbody"><label class="field">Email address<input type="email" autocomplete="email" value="${esc(resumeEmail)}" oninput="resumeEmail=this.value;otpChallenge=null;document.getElementById('resume-code').innerHTML=''"></label><button class="btn primary pre-gap" onclick="sendDemoOtp('resume')">Send test code</button><div id="resume-code" class="pre-gap">${otpChallenge?.purpose==='resume'?otpForm():''}</div></div></div><p class="small muted">Demo verification only; no real authentication or email delivery.</p><button class="link" onclick="startIntake()">Back to application start →</button></section>`}
function preSample(){modal('Sample — not your personalised draft',`<div class="callout"><span>This illustrates the bilingual layout. Your personalised draft becomes available after the required questionnaire and uploads are complete.</span></div><div class="pre-paper-cols pre-gap"><div><h3>Distribution of my estate</h3><p>Primary beneficiary 1: <mark>60%</mark></p><p>Primary beneficiary 2: <mark>40%</mark></p><p class="small muted">Fictional sample choices only.</p></div><div lang="ar" dir="rtl"><h3>توزيع تركتي</h3><p>المستفيد الأول: <mark>٦٠٪</mark></p><p>المستفيد الثاني: <mark>٤٠٪</mark></p><p>نموذج توضيحي فقط</p></div></div><hr class="divider"><p class="small muted">Full legal clauses and translation require the approved bilingual template. This sample cannot be used as a Will.</p><button class="btn primary pre-gap" onclick="closeModal()">Back to where I was</button>`)}
function preTerms(title){modal(title+' · prototype',`<p>This is a testing screen, with no payment, contract or service activated.</p><p class="pre-gap">${title==='Service Terms'?'The live service must display the approved scope, cancellation and refund terms before collecting payment.':'This prototype stores test text and document filenames on this browser. Do not enter real identity or payment information. Live privacy and retention terms must be supplied before launch.'}</p><button class="btn primary pre-gap" onclick="closeModal()">Close</button>`)}
function preHelp(){modal('Before you pay',`<p>Get clarity on your package and documents before starting.</p><div class="pre-faq"><details open><summary>Not sure about a scope question?</summary><p>The OWA team should check your situation before payment if you answer No to age, nationality or UAE assets.</p></details><details><summary>Missing a passport?</summary><p>Passports are needed for everyone named in the Will. After payment you can raise a ticket to discuss missing documents; support does not waive the requirement automatically.</p></details></div><div class="callout pre-gap"><span>The website chatbot will be integrated later. This sample does not send a message. Support tickets unlock only after OWA payment.</span></div><button class="btn primary pre-gap" onclick="closeModal()">Return to application</button>`)}
function signOutDemo(){demoSession=false;otpChallenge=null;resumeEmail='';closeModal();preGo('resume')}

function render(){const views={choose:preChoose,about:preAbout,checkout:preCheckout,payment:prePayment,success:preSuccess,resume:preResume,pending:prePending};$('#app').innerHTML=preHeader()+storageBanner()+`<main id="main" tabindex="-1" class="pre-main">${['choose','about','checkout','payment'].includes(preView)?preProgress():''}<div class="errorbox" id="pre-errors" role="alert" tabindex="-1"></div>${(views[preView]||preChoose)()}</main><footer class="pre-footer"><div class="style-footer-top"><div><div class="style-footer-title">Online Wills Advisor</div><p>A guided way to prepare your Will, with bilingual drafting and support for your application.</p></div><div class="style-footer-links"><button onclick="preSample()">Sample Will</button><button onclick="preHelp()">Get help</button><button onclick="preTerms('Privacy Policy')">Privacy Policy</button><button onclick="preTerms('Service Terms')">Service Terms</button></div></div><div class="style-footer-note">Pre-payment review · Use fictional details. Payments and verification are simulated. This prototype does not generate a court-ready Will.</div></footer>`}
function completePayment(){const j=journey();if(j.payment!=='pending')return;const e=[...scopeErrors(),...aboutErrors(),...contactErrors()];if(!j.terms)e.push('Accept the test terms before payment.');if(e.length)return preErrors(e);j.payment='paid';j.paidAt=new Date().toISOString();j.amountPaid=serviceFee();demoSession=true;save();preView='success';render()}
function preSuccess(){if(journey().payment!=='paid')return preChoose();if(!demoSession)return preResume();return `<section class="pre-centered"><span class="pill green">Test payment successful</span><h1>Payment received.</h1><p class="sub">${packageTitle()} · OWA service fee AED ${money(journey().amountPaid)}</p><div class="card pre-gap"><div class="cardbody"><h3>Next: open your questionnaire.</h3><p class="small muted">In the full platform, we will verify your email when you access your paid account. Your name, contact details and answers carry into the questionnaire.</p><p class="small muted">This separate review file ends here. The existing full-journey HTML contains the after-payment screens.</p><p class="pre-court">Court fee: AED ${money(courtFee())}, payable separately and directly to ADJD.</p></div></div><button class="btn primary pre-gap" onclick="resetJourney()">Test another pre-payment journey</button></section>`}
function resetJourney(){state={saved:0,journey:freshIntake()};demoSession=false;preView='choose';otpChallenge=null;otpNextSend=0;resumeEmail='';paymentOutcome='success';save();closeModal();render()}
function auditExample(pkg='individual'){state={saved:0,journey:freshIntake()};Object.assign(journey(),{package:pkg,step:3,name:'Alex Example'});journey().applicants.forEach(a=>Object.assign(a,{age:true,national:true,assets:true,married:true,children:true}));demoSession=false;otpChallenge=null;otpNextSend=0;preView='checkout';save();closeModal();render()}
function openTesting(){modal('Pre-payment test controls',`<div class="stack"><button class="btn primary" onclick="auditExample('individual')">Review individual checkout</button><button class="btn" onclick="auditExample('couples')">Review couples checkout</button><button class="btn" onclick="resetJourney()">Start fresh at first question</button>${journey().payment==='paid'?'<button class="btn" onclick="signOutDemo()">Test returning customer</button>':''}</div><hr class="divider"><label class="field">Next test payment result<select onchange="paymentOutcome=this.value"><option value="success" ${paymentOutcome==='success'?'selected':''}>Successful</option><option value="declined" ${paymentOutcome==='declined'?'selected':''}>Declined</option><option value="pending" ${paymentOutcome==='pending'?'selected':''}>Pending / unknown</option></select></label>${journey().payment==='pending'?'<button class="btn pre-gap" onclick="closeModal();completePayment()">Resolve pending test payment as successful</button>':''}<p class="small muted pre-gap">Returning-customer demo code: 123456. No email or payment is sent. Example buttons replace only this separate file’s test intake.</p>`)}
function openFlowMap(){modal('Pre-payment screens',`<ol class="pre-flow"><li>Package choice and scope questions, with no price</li><li>Package and short scope questions</li><li>About you: name, marriage and children</li><li>Review inclusions, contact details, OWA fee and separate court fee</li><li>Payment method and test payment outcome</li></ol><p class="small muted">Email OTP is used to access a saved application, not before payment. The paid questionnaire is in the separate full-journey artifact.</p>`)}
function openGuide(){modal('Pre-payment developer notes',`<p>This artifact isolates the pre-payment flow for review. It does not update the existing full-journey file or its stored application.</p><table class="guidetable"><tr><td>Checkout change</td><td>Editorial styling: navy header, restrained red action, Inter body and Georgia headings. Fonts embedded for offline use. First package and scope screen with no price, four-step progress, clear fee alignment, four interactive inclusions, separate ADJD fee disclosure, and a distinct test payment screen. The earlier preview cards and document-readiness block remain removed; no review-timing promise is displayed.</td></tr><tr><td>OWA payment</td><td>AED 999 individual / AED 1,799 couples. Show only this amount payable now. Court fee AED 950 per Will is a separate direct-to-ADJD note.</td></tr><tr><td>Data handoff</td><td>Package, testator 1 name/contact details and each testator’s scope, marriage and children answers must populate the paid questionnaire in the full platform.</td></tr><tr><td>Template wording</td><td>The inclusion text describes the intended service. This HTML does not generate a court-ready Will. Use the approved bilingual template and verified production renderer for actual output.</td></tr><tr><td>Integration boundary</td><td>OTP and payment are simulated. Live authentication, payment confirmation, terms, storage and questionnaire handoff require production integration.</td></tr><tr><td>Conversion measurement</td><td>Compare checkout completion and step abandonment against the prior version. Track validation failures, payment-screen arrival, payment initiation and payment success without sending personal details to analytics. These are test hypotheses; no conversion uplift has been measured.</td></tr></table>`)}
try{const stored=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');if(stored&&stored.journey&&Array.isArray(stored.journey.applicants)&&stored.journey.applicants.length===2&&typeof stored.journey.name==='string'){state=stored;preView=journey().payment==='paid'?'resume':journey().payment==='pending'?'pending':journey().step===3?'checkout':journey().step===2?'about':journey().step===1?'choose':'landing'}else{state.journey=freshIntake();Object.assign(journey(),{package:'individual',step:3,name:'Alex Example'});journey().applicants.forEach(a=>Object.assign(a,{age:true,national:true,assets:true,married:true,children:true}));preView='checkout'}}catch{state.journey=freshIntake();storageIssue='Browser storage unavailable. Progress lasts only while this page stays open.'}
function emailVerified(){const j=journey();return !!j.verifiedEmail&&j.verifiedEmail===j.email.trim().toLowerCase()}
function checkoutAction(){const e=[...scopeErrors(),...aboutErrors(),...contactErrors()];if(e.length)return preErrors(e);preGo('payment')}
function focusContact(){const target=$('#demo-otp')||$('#checkout-email');target?.scrollIntoView({behavior:'smooth',block:'center'});target?.focus({preventScroll:true});toast(otpChallenge?'Enter the test code to finish verifying your email.':'Add your contact details, then verify your email to continue.')}
function checkoutButton(){return `<button id="checkout-action" class="btn primary pre-pay-button" onclick="checkoutAction()">Continue to payment ${ico('arrow')}</button><p id="checkout-action-hint" class="cro-cta-hint">Continue to the payment screen; no card details are collected here.</p>`}
function mobileCheckoutText(){return 'Continue to payment'}
function refreshCheckoutAction(){const el=$('#checkout-action-slot');if(el)el.innerHTML=checkoutButton();const mobile=$('#mobile-checkout-action');if(mobile)mobile.textContent=mobileCheckoutText()+' →'}
function preHeader(){const funnel=['choose','about','checkout','payment','pending','success'].includes(preView);return `<div class="testbar"><span class="testlabel">PRE-PAYMENT REVIEW · No real charges · Demo code 123456</span><div class="row"><button onclick="openTesting()">Test controls</button><button onclick="openFlowMap()">Screen map</button><button onclick="openGuide()">Developer notes</button></div></div><header class="topbar cro-header"><button class="pre-brand" onclick="preGo('choose')" aria-label="OWA application start"><span class="brand">owa<span>Online Wills<br>Advisor</span></span></button>${funnel?'<div class="cro-header-help"><span class="small muted">A question before you continue?</span><button class="link small" onclick="preHelp()">Get help →</button></div>':`<nav aria-label="Public navigation"><button onclick="preGo('choose')">Start</button><button onclick="preHelp()">Questions?</button></nav><button class="btn small" onclick="preGo('resume')">Resume application</button>`}</header>`}

function inclusionExplorer(){return `<div class="cro-benefit-explorer">
  <div class="cro-benefit-tabs" role="group" aria-label="Explore what is included">
    <button type="button" data-benefit-toggle="guided" aria-pressed="true" class="active" onclick="showBenefit('guided')"><span class="cro-tab-number">01</span> Guided questions</button>
    <button type="button" data-benefit-toggle="draft" aria-pressed="false" onclick="showBenefit('draft')"><span class="cro-tab-number">02</span> Bilingual draft</button>
    <button type="button" data-benefit-toggle="support" aria-pressed="false" onclick="showBenefit('support')"><span class="cro-tab-number">03</span> In-app support</button>
    <button type="button" data-benefit-toggle="court" aria-pressed="false" onclick="showBenefit('court')"><span class="cro-tab-number">04</span> ADJD submission</button>
  </div>
  <div class="cro-benefit-stage">
    <section class="cro-benefit-panel" data-benefit="guided">
      <svg viewBox="0 0 250 158" role="img" aria-label="Illustration of the guided questionnaire with saved sections"><rect width="250" height="158" rx="12" fill="#efe9f7"/><rect x="22" y="17" width="206" height="124" rx="9" fill="white" stroke="#ded3ec"/><rect x="22" y="17" width="206" height="29" rx="9" fill="#302342"/><circle cx="40" cy="31" r="4" fill="#d7c4eb"/><rect x="52" y="28" width="91" height="6" rx="3" fill="#d7c4eb"/><rect x="39" y="60" width="84" height="6" rx="3" fill="#4c3a62"/><rect x="39" y="74" width="170" height="8" rx="4" fill="#eee9f3"/><rect x="39" y="90" width="170" height="8" rx="4" fill="#eee9f3"/><rect x="39" y="108" width="112" height="8" rx="4" fill="#eee9f3"/><circle cx="194" cy="112" r="13" fill="#e6f4e9"/><path d="m188 112 4 4 8-9" fill="none" stroke="#357956" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg>
      <div><span class="eyebrow">SIX SECTIONS · SAVE AS YOU GO</span><strong>Make your wishes clear, step by step</strong><p>A six-section questionnaire guides your beneficiaries, executors and guardians where needed. Progress saves automatically.</p></div>
    </section>
    <section class="cro-benefit-panel" data-benefit="draft" hidden>
      <svg viewBox="0 0 250 158" role="img" aria-label="Illustration of an English and Arabic draft side by side"><rect width="250" height="158" rx="12" fill="#efe9f7"/><rect x="36" y="14" width="178" height="132" rx="5" fill="white" stroke="#d4c7e4"/><rect x="53" y="27" width="68" height="8" rx="4" fill="#3c2a58"/><rect x="128" y="27" width="68" height="8" rx="4" fill="#3c2a58"/><path d="M125 44v86" stroke="#ddd2e9"/><path d="M53 50h58M53 63h57M53 76h48M53 89h57M53 102h52M53 115h40M139 50h57M139 63h57M147 76h49M139 89h57M143 102h53M156 115h40" stroke="#b6a8ca" stroke-width="4" stroke-linecap="round"/></svg>
      <div><span class="eyebrow">ENGLISH + ARABIC</span><strong>Your Will in English and Arabic</strong><p>A bilingual draft prepared using the ADJD Will template, with your details and choices. You can review the generated draft after completing the questionnaire.</p></div>
    </section>
    <section class="cro-benefit-panel" data-benefit="support" hidden>
      <svg viewBox="0 0 250 158" role="img" aria-label="Illustration of a document and in-app support conversation"><rect width="250" height="158" rx="12" fill="#efe9f7"/><rect x="28" y="20" width="112" height="116" rx="7" fill="white" stroke="#d4c7e4"/><path d="M45 47h69M45 61h69M45 75h50M45 90h63" stroke="#c3b4d6" stroke-width="5" stroke-linecap="round"/><rect x="117" y="64" width="100" height="52" rx="10" fill="#38254d"/><path d="m134 116-13 13 2-14" fill="#38254d"/><circle cx="146" cy="90" r="4" fill="#efe3fd"/><circle cx="167" cy="90" r="4" fill="#efe3fd"/><circle cx="188" cy="90" r="4" fill="#efe3fd"/></svg>
      <div><span class="eyebrow">HELP AFTER PAYMENT</span><strong>Help with documents and questions</strong><p>In-app support tickets and document assistance are included after payment.</p></div>
    </section>
    <section class="cro-benefit-panel" data-benefit="court" hidden>
      <svg viewBox="0 0 250 158" role="img" aria-label="Document reviewed and submitted to ADJD"><rect x="42" y="12" width="164" height="134" rx="3" fill="#fff" stroke="#b9c1cd"/><path d="M64 39h121M64 52h97M64 69h121M64 82h107M64 99h82" stroke="#c8ced6" stroke-width="4" stroke-linecap="round"/><circle cx="174" cy="111" r="19" fill="#e7ecea"/><path d="m165 111 6 6 12-14" fill="none" stroke="#245c4a" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg>
      <div><span class="eyebrow">AFTER REVIEW AND COURT PAYMENT</span><strong>ADJD court submission</strong><p>OWA prepares and submits your completed application to ADJD after review and direct payment of the court fee. ADJD handles the registration decision.</p></div>
    </section>
  </div>
</div>`}
function showBenefit(key){document.querySelectorAll('[data-benefit-toggle]').forEach(button=>{const active=button.getAttribute('data-benefit-toggle')===key;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active))});document.querySelectorAll('[data-benefit]').forEach(panel=>{panel.hidden=panel.getAttribute('data-benefit')!==key})}

function prePayment(){const j=journey(),couples=j.package==='couples';return `<div class="pagehead saas-checkout-head"><span class="eyebrow">STEP 4 OF 4 · PAYMENT</span><h1>Complete your checkout</h1><p class="sub">Your Will preparation with Online Wills Advisor.</p></div><div class="saas-checkout"><section class="saas-order" aria-label="Order summary"><div class="saas-order-top"><span class="saas-label">YOUR ORDER</span><button onclick="preGo('choose')">Change</button></div><div class="saas-product"><span class="saas-product-icon" aria-hidden="true"><svg viewBox="0 0 40 44" fill="none"><path d="M9 4h16l8 8v28H9zM25 4v9h8M15 21h12M15 27h12M15 33h8" stroke="currentColor" stroke-width="1.8"/></svg></span><div><h2>${packageTitle()}</h2><p>${couples?'Two separate Wills':'One Will'} · English & Arabic</p></div></div><div class="saas-order-name">Prepared for <strong>${esc(j.name||'you')}${couples?' and your partner':''}</strong></div><div class="saas-price-block"><span>Payable now to OWA</span><div class="saas-price"><span>AED</span><strong>${money(serviceFee())}</strong></div><p>OWA service fee</p></div><div class="saas-inclusions"><h3>Your package includes</h3><ul><li>Six-section questionnaire with auto-save</li><li>English and Arabic Will draft</li><li>Document assistance and in-app support</li><li>Application review and ADJD submission</li></ul></div><button class="saas-sample" onclick="preSample()">View a sample Will ${ico('arrow')}</button><p class="saas-court">ADJD court fee: <strong>AED ${money(courtFee())}${couples?' for two Wills':' per Will'}</strong>, paid directly to ADJD later (not charged by OWA).</p><details class="saas-mobile-included"><summary>View package inclusions</summary><ul><li>Six-section questionnaire with auto-save</li><li>English and Arabic Will draft</li><li>Document assistance and in-app support</li><li>Application review and ADJD submission</li></ul><button class="saas-sample" onclick="preSample()">View a sample Will</button></details></section><section class="saas-pay" aria-label="Payment"><div class="saas-pay-heading"><h2>Payment details</h2><span class="saas-test-tag">TEST MODE</span></div><div class="saas-customer"><div class="saas-customer-top"><span>Contact details</span><button class="link" onclick="preGo('checkout')">Edit</button></div><strong>${esc(j.email||'Your email')}</strong><span>${esc(j.phone||'Your phone number')}</span></div><div class="saas-method-label">Payment method</div><div class="saas-method"><span class="saas-method-check" aria-hidden="true">✓</span><svg viewBox="0 0 32 24" fill="none" aria-hidden="true"><rect x="1" y="1" width="30" height="22" rx="3" stroke="currentColor" stroke-width="1.5"/><path d="M1 8h30M6 17h7" stroke="currentColor" stroke-width="1.5"/></svg><div><strong>Card payment</strong><span>Via the payment provider in the live checkout</span></div></div><p class="saas-demo-info">This prototype does not collect card details. Use the button below to simulate payment.</p>${j.payment==='failed'?'<div class="saas-error" role="status"><strong>Payment wasn’t completed.</strong><span>Your answers are saved. You can try again below.</span></div>':''}<div class="saas-total"><span>Payable now</span><strong>AED ${money(serviceFee())}</strong></div><label class="saas-terms"><input id="payment-terms" type="checkbox" ${j.terms?'checked':''} onchange="journey().terms=this.checked;save()"><span>I agree to the Service Terms for this test.</span></label><div class="saas-policy"><button class="link" onclick="preTerms('Service Terms')">Service Terms</button><span>·</span><button class="link" onclick="preTerms('Privacy Policy')">Privacy Policy</button></div><button class="btn primary saas-pay-cta" onclick="startPayment()">${j.payment==='failed'?'Retry payment':'Pay'} AED ${money(serviceFee())} ${ico('arrow')}</button><p class="saas-nocharge">Test payment only. No charge or receipt is issued.</p><div class="saas-next"><span aria-hidden="true">→</span><p><strong>Next: your guided questionnaire</strong><span>Verify your email after payment to access your application and in-app support.</span></p></div></section></div><div class="saas-checkout-foot"><button class="link" onclick="preGo('checkout')">← Back to review</button><button class="link" onclick="preHelp()">Questions before paying?</button></div><div class="saas-questions"><details><summary>What happens after I pay?</summary><p>Verify your email to open your paid application. Add documents and complete the six sections${couples?' for both Wills':''}, then review your bilingual draft. OWA reviews your completed application before submission to ADJD.</p></details><details><summary>Do I need my documents now?</summary><p>No. Upload your identity documents in the questionnaire after payment. You can save your progress and return later.</p></details><details><summary>Does this complete court registration?</summary><p>No. This payment starts Will preparation. The court fee is paid directly to ADJD later. OWA submits your completed application after review and court payment; ADJD decides registration.</p></details></div><div class="saas-mobile-pay"><span><small>OWA service fee · test</small><strong>AED ${money(serviceFee())}</strong></span><button class="btn primary" onclick="saasMobilePay()">Continue to pay ${ico('arrow')}</button></div>`}
function saasMobilePay(){if(!journey().terms){const t=document.querySelector('#payment-terms');t?.scrollIntoView({block:'center',behavior:'smooth'});t?.focus({preventScroll:true});return}startPayment()}

function preCheckout(){const j=journey(),couples=j.package==='couples';return `<div class="pagehead cro-checkout-head"><div class="eyebrow">STEP 3 OF 4 · REVIEW</div><h1>Review ${couples?'your two Wills':'your Will'}.</h1><p class="sub">Check your package and contact details. You’ll pay only the OWA service fee at checkout.</p><div class="cro-mobile-price"><strong>AED ${money(serviceFee())} payable to OWA</strong><button id="mobile-checkout-action" class="btn primary small" onclick="checkoutAction()">${mobileCheckoutText()} →</button></div><div class="cro-assurance"><span>${ico('check')} No documents needed at checkout</span><span>${ico('check')} Save and return to your questionnaire</span></div></div><div class="pre-checkout cro-checkout"><section class="card cro-included"><div class="cardbody"><div class="cro-application"><div><span class="eyebrow">${couples?'TWO SEPARATE WILLS':'ONE INDIVIDUAL WILL'}</span><h2>${packageTitle()}</h2><p class="small muted">Prepared for ${esc(j.name||'you')}${couples?' and your partner':''}</p></div><button class="link small" onclick="preGo('about')">Edit details</button></div><hr class="divider"><h3>What is included:</h3>${inclusionExplorer()}<button class="link draft-preview-link" onclick="preSample()">See a sample bilingual Will ${ico('arrow')}</button></div></section><section id="checkout-contact" class="card cro-contact"><div class="cardhead"><div><span class="eyebrow">YOUR CONTACT DETAILS</span><h3>Where should we send your receipt?</h3></div></div><div class="cardbody"><p class="small muted cro-contact-intro">Enter your email and phone number for your receipt and application. You can verify your email when you return to the paid questionnaire.</p><div class="grid2"><label class="field">Email address *<input id="checkout-email" type="email" autocomplete="email" aria-required="true" placeholder="you@example.com" value="${esc(j.email)}" oninput="preInput('email',this.value)"></label><label class="field">Phone number *<input type="tel" autocomplete="tel" aria-required="true" placeholder="+971 50 000 0001" value="${esc(j.phone)}" oninput="preInput('phone',this.value)"><span class="hint">Include your country code. OWA may contact you about your application.</span></label></div></div></section><aside class="cro-order-wrap"><div class="card cro-order"><div class="cardbody"><div class="spread"><span class="eyebrow">PAYABLE TO OWA TODAY</span><button class="link small" onclick="preGo('choose')">Change package</button></div><div class="pre-price premium-price"><span class="premium-price__currency">AED</span><strong>${money(serviceFee())}</strong></div><p class="cro-package-label">${packageTitle()} · ${couples?'two Wills':'one Will'}</p>${j.payment==='failed'?'<div class="callout amber">Payment wasn’t completed. Your answers are saved—please try again.</div>':''}<div id="checkout-action-slot">${checkoutButton()}</div><div class="cro-payment-steps"><span>1 Review details</span><span>2 Payment</span><span>3 Questionnaire</span></div><p class="cro-demo-note">Test checkout only. No real payment is taken.</p><details class="cro-prototype-terms"><summary>About this test</summary><p>Service and refund terms are placeholders. Approved terms must be displayed before accepting live payments.</p></details></div></div><p class="cro-court-line">ADJD court fee: AED ${money(courtFee())}${couples?' for two Wills':' per Will'}, paid directly to ADJD later (not charged by OWA).</p></aside><section class="cro-questions"><h3>Before you continue</h3><div class="pre-faq"><details><summary>Do I need my documents now?</summary><p>No uploads are needed at checkout. You’ll add identity documents and addresses in the questionnaire. Required details and documents must be complete before your draft can be generated.</p></details><details><summary>Can I finish the questionnaire later?</summary><p>Yes. Save your progress and return through email sign-in. This testing file stores intake only on this browser.</p></details><details><summary>What happens after I pay?</summary><p>Your questionnaire and in-app support become available. Complete the required details and documents to generate your draft${couples?'; both Wills must be complete':''}. OWA then reviews the application before submission.</p></details></div><button class="link small pre-gap" onclick="preHelp()">Still have a question? Get help →</button></section></div><div class="actions"><button class="link small" onclick="preGo('about')">← Back to your details</button>${saveLabel()}</div>`}

render();
